const fs = require('fs');
const deliveryDocuments = [
  { path: '/files/ATIVIDADES 1º ANO.pdf', name: 'ATIVIDADES 1º ANO.pdf' },
  { path: '/files/ATIVIDADES 2º ANO.pdf', name: 'ATIVIDADES 2º ANO.pdf' },
  { path: '/files/ATIVIDADES 3º ANO.pdf', name: 'ATIVIDADES 3º ANO.pdf' },
  { path: '/files/ATIVIDADES 4º ANO.pdf', name: 'ATIVIDADES 4º ANO.pdf' },
  { path: '/files/ATIVIDADES 5º ANO.pdf', name: 'ATIVIDADES 5º ANO.pdf' },
  { path: '/files/ATIVIDADES 6º ANO.pdf', name: 'ATIVIDADES 6º ANO.pdf' },
  { path: '/files/ATIVIDADES 7º ANO.pdf', name: 'ATIVIDADES 7º ANO.pdf' },
  { path: '/files/ATIVIDADES 8º ANO.pdf', name: 'ATIVIDADES 8º ANO.pdf' },
  { path: '/files/ATIVIDADES 9º ANO.pdf', name: 'ATIVIDADES 9º ANO.pdf' },
  { path: '/files/Universo Pedagogico - Entrega.pdf', name: 'Universo Pedagogico - Entrega.pdf' },
];
const deliveryInstructions = [
  '🎉 Compra confirmada, amiga! 💙',
  '',
  'Muito obrigada pela sua compra! Logo abaixo está o PDF com acesso às suas atividades + bônus. ✨',
  '',
  'Para acessar é bem simples:',
  '',
  '1. Clique e abra o PDF.',
  '2. Arraste para baixo para ver todas as páginas.',
  '3. Clique em “Abrir Atividades” ou “Acessar Bônus”.',
  '4. Prontinho! Você será redirecionada para os seus materiais. 🥰',
  '',
  '📚 Esperamos que você aproveite muito suas atividades e seu bônus!'
].join('\n');
const output = [];
for (const item of $input.all()) {
  const type = item.json.messageType;
  if (type === 'payment_thanks') {
    output.push({ json: { ...item.json, sendKind: 'text', text: 'Pagamento confirmado! Muito obrigado pela confiança e pelo apoio ao nosso projeto. 💚' } });
    continue;
  }
  if (type === 'payment_release_approved') {
    output.push({ json: { ...item.json, sendKind: 'text', text: 'Pagamento aprovado ✅' } });
    continue;
  }
  if (type === 'payment_release_instructions') {
    output.push({ json: { ...item.json, sendKind: 'text', text: deliveryInstructions } });
    continue;
  }
  if (type === 'payment_release_pdf') {
    for (const document of deliveryDocuments) {
      if (!fs.existsSync(document.path)) throw new Error('PDF de entrega ausente em ' + document.path);
      output.push({
        json: {
          ...item.json,
          sendKind: 'document',
          fileName: document.name,
          caption: document.name,
          documentBase64: fs.readFileSync(document.path).toString('base64'),
        },
      });
    }
    continue;
  }
  if (type === 'payment_release') {
    output.push({ json: { ...item.json, sendKind: 'text', text: 'Pagamento aprovado ✅' } });
    continue;
  }
  if (type === 'payment_admin_notify') {
    const amount = item.json.payload?.amount ? String(item.json.payload.amount).replace('.', ',') : 'não informado';
    const customer = item.json.payload?.customer || 'Cliente';
    const phone = item.json.payload?.customerPhone || '';
    const text = ['Pagamento confirmado no Mercado Pago ✅', '', `Cliente: ${customer}`, `Telefone: ${phone}`, `Valor: R$ ${amount}`].join('\n');
    output.push({ json: { ...item.json, sendKind: 'text', text } });
    continue;
  }
  throw new Error(`Tipo de outbox não suportado: ${type}`);
}
return output;
